contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this) == c.owner());

        uint balBefore = address(c).balance;
        uint ownerBefore = uint(uint160(c.owner()));
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint thisBalBefore = address(this).balance;

        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            reverted == (balBefore < v) &&
            uint(uint160(c.owner())) == ownerBefore &&
            c.depositsCount() == depositsBefore &&
            (
                reverted
                    ? (address(c).balance == balBefore && address(this).balance == thisBalBefore)
                    : (address(c).balance == balBefore - v && address(this).balance == thisBalBefore + v)
            )
        );
    }

    receive() external payable {}
}

