    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 v) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this) == c.owner());
        uint balBefore = address(c).balance;
        uint ownerBefore = uint(uint160(c.owner()));
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        uint thisBalBefore = address(this).balance;
        bool reverted;
        try c.withdraw(v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == (balBefore < v) &&
            uint(uint160(c.owner())) == ownerBefore &&
            c.depositsCount() == depositsBefore &&
            (
                reverted
                    ? (address(c).balance == balBefore && address(this).balance == thisBalBefore)
                    : (address(c).balance == balBefore - v && address(this).balance == thisBalBefore + v)
            ));
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
